627e7424-0d21-46e0-981c-453628e75b69	content_card	card-lxezirry	create	\N	{"id": "card-lxezirry", "href": "/mistse/tsentr-kultury-vyna-shabo-bqalqv", "title": "Центр культури вина “Шабо”", "city_id": "city-jei7cmx8", "payload": {"placeId": "place-9jn9i9ew", "description": "<p><strong>Центр культури вина “Шабо”</strong> — це унікальний еногастрономічний комплекс у самому серці Шабівської громади, де поєднуються виноробні традиції, сучасні технології та туристичний досвід європейського рівня. Розташований серед мальовничих виноградників площею понад 1200 гектарів і з більш ніж 4 мільйонами лоз, центр є одним із наймасштабніших винних просторів України, що працює цілий рік і відкриває гостям світ справжньої культури вина.</p>"}, "page_key": "index", "subtitle": "с. Шабо, вул.Швейцарська,10", "card_type": "attraction", "image_url": "https://tourism.od.gov.ua/storage/v1/object/public/media/1780919169052-ozndrq1f18.png", "published": true, "region_id": null, "sort_order": 4, "district_id": "district-07uz711u", "section_key": "attractions"}	\N	2026-06-08 11:46:59.986483+00
