cfccc413-cbaa-4e8b-9dd0-e3a61f51414a	tourism_object	place-6n105u7t	update	{"id": "place-6n105u7t", "name": "Парк мініатюр", "slug": "park-miniatyur-x50ucr", "type": "attraction", "hours": "Пн-Пт: 09:00-17:00 / Сб-Нд: 10:30-15:00", "phone": "+38 098 529 4967", "address": "м.Ізмаїл проспект Суворова, 51", "city_id": "city-qnaz943c", "map_url": "https://maps.app.goo.gl/wfpfXZSQNk94dUma6", "name_en": null, "website": null, "hours_en": null, "reel_url": null, "subtitle": "Парк-музей", "venue_id": null, "amenities": null, "image_url": "https://omore.city/upload/article/o_1hr3vfbj97dq1s3k1sik14qt11u02e.jpg", "published": true, "video_url": null, "address_en": null, "created_at": "2026-06-12T13:47:44.526708+03:00", "repertoire": null, "description": "<p>Парк мініатюр в Ізмаїлі — унікальна туристична локація, яка дозволяє побачити головні архітектурні перлини міста в одному місці. Тут історія українського Придунав’я оживає у витончених мініатюрних копіях відомих храмів, історичних будівель та пам’яток, що формували образ Ізмаїла протягом століть.</p>", "district_id": "district-inxqkycm", "event_dates": null, "subtitle_en": null, "amenities_en": null, "detailed_info": "<p>Відкритий у 2019 році парк став справжньою візитівкою міста та популярним місцем для прогулянок і знайомства з його культурною спадщиною. Серед експонатів — мініатюри Покровського кафедрального собору, Свято-Успенської та Свято-Миколаївської церков, будівлі колишньої міської думи та інших знакових об’єктів Ізмаїла. Кожна модель відтворена з високою деталізацією та допомагає краще зрозуміти історію міста.</p><p>Парк поєднує пізнавальний відпочинок із затишною атмосферою для всієї родини. Охайні алеї, зручні оглядові майданчики, місця для відпочинку та фотозони роблять його чудовим простором для неспішних прогулянок і яскравих світлин. Локація однаково цікава як туристам, так і мешканцям міста.</p><p>Парк мініатюр — це можливість здійснити захопливу подорож архітектурною спадщиною Ізмаїла всього за одну прогулянку. Саме тут найкраще розпочати знайомство з містом, надихнутися його історією та відкрити для себе багатий культурний світ українського Придунав’я.</p>", "tourism_types": ["Історико-культурний туризм"], "description_en": null, "hero_font_size": null, "reel_image_url": null, "detailed_info_en": null}	{"id": "place-6n105u7t", "name": "Парк мініатюр", "slug": "park-miniatyur-x50ucr", "type": "attraction", "hours": "Пн-Пт: 09:00-17:00 / Сб-Нд: 10:30-15:00", "phone": "+38 098 529 4967", "address": "м.Ізмаїл проспект Суворова, 51", "city_id": "city-qnaz943c", "map_url": "https://maps.app.goo.gl/wfpfXZSQNk94dUma6", "name_en": null, "website": null, "hours_en": null, "reel_url": null, "subtitle": "Парк-музей", "venue_id": null, "amenities": null, "image_url": "https://omore.city/upload/article/o_1hr3vfbj97dq1s3k1sik14qt11u02e.jpg", "published": true, "video_url": null, "address_en": null, "repertoire": null, "description": "<p>Парк мініатюр в Ізмаїлі — унікальна туристична локація, яка дозволяє побачити головні архітектурні перлини міста в одному місці. Тут історія українського Придунав’я оживає у витончених мініатюрних копіях відомих храмів, історичних будівель та пам’яток, що формували образ Ізмаїла протягом століть.</p>", "district_id": "district-inxqkycm", "event_dates": null, "subtitle_en": null, "amenities_en": null, "detailed_info": "<p>Відкритий у 2019 році парк став справжньою візитівкою міста та популярним місцем для прогулянок і знайомства з його культурною спадщиною. Серед експонатів — мініатюри Покровського кафедрального собору, Свято-Успенської та Свято-Миколаївської церков, будівлі колишньої міської думи та інших знакових об’єктів Ізмаїла. Кожна модель відтворена з високою деталізацією та допомагає краще зрозуміти історію міста.</p><p>Парк поєднує пізнавальний відпочинок із затишною атмосферою для всієї родини. Охайні алеї, зручні оглядові майданчики, місця для відпочинку та фотозони роблять його чудовим простором для неспішних прогулянок і яскравих світлин. Локація однаково цікава як туристам, так і мешканцям міста.</p><p>Парк мініатюр — це можливість здійснити захопливу подорож архітектурною спадщиною Ізмаїла всього за одну прогулянку. Саме тут найкраще розпочати знайомство з містом, надихнутися його історією та відкрити для себе багатий культурний світ українського Придунав’я.</p>", "tourism_types": ["Історико-культурний туризм", "Розважальний туризм"], "description_en": null, "hero_font_size": null, "reel_image_url": null, "detailed_info_en": null}	\N	2026-06-12 10:50:39.924555+00
